import shutil
import time
from pathlib import Path

from agents import function_tool


@function_tool
def archive_and_remove_old_files(source_directory: str, archive_directory: str, minimum_age_in_days: int) -> str:
    source_directory_path = Path(source_directory)
    archive_directory_path = Path(archive_directory)
    archive_directory_path.mkdir(parents=True, exist_ok=True)

    cutoff_timestamp_in_seconds = time.time() - minimum_age_in_days * 86400
    number_of_files_moved = 0

    for each_candidate_file_path in source_directory_path.rglob("*"):
        if each_candidate_file_path.is_file() and each_candidate_file_path.stat().st_mtime < cutoff_timestamp_in_seconds:
            destination_file_path = archive_directory_path / each_candidate_file_path.name
            shutil.move(str(each_candidate_file_path), str(destination_file_path))
            number_of_files_moved += 1

    number_of_empty_folders_deleted = 0
    for each_subfolder_path in sorted(source_directory_path.rglob("*"), reverse=True):
        if each_subfolder_path.is_dir() and not any(each_subfolder_path.iterdir()):
            each_subfolder_path.rmdir()
            number_of_empty_folders_deleted += 1

    return "Moved %d files and deleted %d empty folders" % (number_of_files_moved, number_of_empty_folders_deleted)
